```javascript
function handleBrickCollision(ball, brick) {
  const dx1 = ball.x + ball.r - brick.x; // distance to left edge
  const dx2 = brick.x + brick.w - (ball.x - ball.r); // distance to right edge
  const dy1 = ball.y + ball.r - brick.y; // distance to top edge
  const dy2 = brick.y + brick.h - (ball.y - ball.r); // distance to bottom edge

  const overlapX = Math.min(dx1, dx2);
  const overlapY = Math.min(dy1, dy2);

  if (overlapX < overlapY) {
    // Side hit
    if (dx1 < dx2) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (overlapY < overlapX) {
    // Top/Bottom hit
    if (dy1 < dy2) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // Corner hit (exact equality)
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    // Push out is tricky here, maybe just use the signs of vx/vy to decide
    if (dx1 < dx2) ball.x = brick.x - ball.r; else ball.x = brick.x + brick.w + ball.r;
    if (dy1 < dy2) ball.y = brick.y - ball.r; else ball.y = brick.y + brick.h + ball.r;
  }
}
```

