/**
 * Checks for and resolves collision between the ball and a set of bricks.
 * Implements arcade-style bounces: per-face deflection and push-out.
 * Also handles tunnelling by checking the path between the previous and current position.
 */
export function brickHit(ball, bricks, dt) {
  const prevX = ball.x - ball.vx * dt;
  const prevY = ball.y - ball.vy * dt;

  let hitBrick = null;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    let colliding = collides(ball, brick);

    // Tunnelling detection: check if the ball crossed the brick during this frame
    if (!colliding) {
      const minX = Math.min(prevX - ball.r, ball.x - ball.r);
      const maxX = Math.max(prevX + ball.r, ball.x + ball.r);
      const minY = Math.min(prevY - ball.r, ball.y - ball.r);
      const maxY = Math.max(prevY + ball.r, ball.y + ball.r);

      if (maxX > brick.x && minX < brick.x + brick.w && maxY > brick.y && minY < brick.y + brick.h) {
        colliding = true;
      }
    }

    if (colliding) {
      hitBrick = brick;
      break; // Resolve only the first hit to avoid "double-bounces" at seams
    }
  }

  if (hitBrick) {
    const brick = hitBrick;
    const dx1 = ball.x + ball.r - brick.x; // overlap with left edge
    const dx2 = brick.x + brick.w - (ball.x - ball.r); // overlap with right edge
    const dy1 = ball.y + ball.r - brick.y; // overlap with top edge
    const dy2 = brick.y + brick.h - (ball.y - ball.r); // overlap with bottom edge

    const overlapX = Math.min(dx1, dx2);
    const overlapY = Math.min(dy1, dy2);

    if (overlapX < overlapY) {
      // Side hit
      if (dx1 < dx2) {
        ball.x = brick.x - ball.r;
        ball.vx = -Math.abs(ball.vx);
      } else {
        ball.x = brick.x + brick.w + ball.r;
        ball.vx = Math.abs(ball.vx);
      }
    } else if (overlapY < overlapX) {
      // Top/Bottom hit
      if (dy1 < dy2) {
        ball.y = brick.y - ball.r;
        ball.vy = -Math.abs(ball.vy);
      } else {
        ball.y = brick.y + brick.h + ball.r;
        ball.vy = Math.abs(ball.vy);
      }
    } else {
      // Corner hit: flip both
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      // Push out based on current velocity signs to avoid sticking
      ball.x = ball.vx > 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
      ball.y = ball.vy > 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
    }
    return true;
  }

  return false;
}

